# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SİNÜS VE KOSİNÜS TOPLAM - FARK FORMÜLLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">SİNÜS FORMÜLLERİ (Paylaşımcı &amp; Aynı İşaret)</text>\n  <rect x="40" y="88" width="285" height="58" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="182" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">sin(a + b) = sin(a)·cos(b) + cos(a)·sin(b)</text>\n  <text x="182" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">sin(a - b) = sin(a)·cos(b) - cos(a)·sin(b)</text>\n  <text x="42" y="168" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">sin(15°)</tspan> = sin(45° - 30°) = (kök(6) - kök(2)) / 4</text>\n  <text x="42" y="190" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">sin(75°)</tspan> = sin(45° + 30°) = (kök(6) + kök(2)) / 4</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Kodlama: "sin·cos ± cos·sin" (İşaret değişmez)</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KOSİNÜS FORMÜLLERİ (Bencil &amp; Zıt İşaret)</text>\n  <rect x="375" y="88" width="285" height="58" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="517" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">cos(a + b) = cos(a)·cos(b) - sin(a)·sin(b)</text>\n  <text x="517" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">cos(a - b) = cos(a)·cos(b) + sin(a)·sin(b)</text>\n  <text x="377" y="168" font-size="11" fill="#14532d">• <tspan font-weight="bold">cos(15°)</tspan> = cos(45° - 30°) = (kök(6) + kök(2)) / 4</text>\n  <text x="377" y="190" font-size="11" fill="#14532d">• <tspan font-weight="bold">cos(75°)</tspan> = cos(45° + 30°) = (kök(6) - kök(2)) / 4</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kodlama: "cos·cos ∓ sin·sin" (İşaret ters döner)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TANJANT VE KOTANJANT TOPLAM - FARK BAĞINTILARI</text>\n  <rect x="25" y="48" width="320" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">TANJANT TOPLAM VE FARK</text>\n  <rect x="42" y="88" width="286" height="44" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="185" y="115" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">tan(a + b) = [tan(a) + tan(b)] / [1 - tan(a)·tan(b)]</text>\n  <rect x="42" y="140" width="286" height="44" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="185" y="167" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">tan(a - b) = [tan(a) - tan(b)] / [1 + tan(a)·tan(b)]</text>\n  <text x="42" y="206" font-size="11" fill="#78350f">• <tspan font-weight="bold">tan(15°)</tspan> = tan(45° - 30°) = 2 - kök(3)</text>\n  <text x="42" y="226" font-size="11" fill="#78350f">• <tspan font-weight="bold">tan(75°)</tspan> = tan(45° + 30°) = 2 + kök(3)</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">ÖZEL DURUMLAR VE PRATİK İPUÇLARI</text>\n  <text x="378" y="98" font-size="11" fill="#581c87">• <tspan font-weight="bold">tan(45° + a)</tspan> = (1 + tan(a)) / (1 - tan(a))</text>\n  <text x="378" y="122" font-size="11" fill="#581c87">• <tspan font-weight="bold">tan(45° - a)</tspan> = (1 - tan(a)) / (1 + tan(a))</text>\n  <text x="378" y="146" font-size="11" fill="#581c87">• <tspan font-weight="bold">Kotanjant Geçişi:</tspan> cot(a ± b) = 1 / tan(a ± b)</text>\n  <text x="378" y="170" font-size="11" fill="#581c87">• Eğer <tspan font-weight="bold">a + b = 45°</tspan> ise:</text>\n  <text x="388" y="190" font-size="12" font-weight="bold" fill="#7e22ce">(1 + tan(a)) · (1 + tan(b)) = 2</text>\n  <rect x="378" y="202" width="279" height="28" rx="5" fill="#ffffff" stroke="#c084fc"/>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">tan(90°) tanımsız ise payda: 1 - tan(a)·tan(b) = 0</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KARE VE DİK ÜÇGEN ÜZERİNDE TOPLAM-FARK UYGULAMALARI</text>\n  <rect x="25" y="48" width="310" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Kare İçinde Açı Taşıma (θ = 90° - (α + β))</text>\n  <rect x="75" y="85" width="130" height="130" fill="#ffffff" stroke="#1e40af" stroke-width="2"/>\n  <line x1="75" y1="85" x2="205" y2="150" stroke="#dc2626" stroke-width="2"/>\n  <line x1="75" y1="85" x2="140" y2="215" stroke="#dc2626" stroke-width="2"/>\n  <text x="62" y="82" font-size="11" font-weight="bold" fill="#0f172a">A</text>\n  <text x="210" y="82" font-size="11" font-weight="bold" fill="#0f172a">B</text>\n  <text x="210" y="222" font-size="11" font-weight="bold" fill="#0f172a">C</text>\n  <text x="62" y="222" font-size="11" font-weight="bold" fill="#0f172a">D</text>\n  <text x="115" y="102" font-size="11" font-weight="bold" fill="#2563eb">α</text>\n  <text x="102" y="120" font-size="12" font-weight="bold" fill="#dc2626">θ</text>\n  <text x="83" y="135" font-size="11" font-weight="bold" fill="#16a34a">β</text>\n  <text x="220" y="120" font-size="11" fill="#1e3a8a">• α + θ + β = 90°</text>\n  <text x="220" y="142" font-size="11" fill="#1e3a8a">• θ = 90° - (α + β)</text>\n  <text x="220" y="164" font-size="11" font-weight="bold" fill="#1d4ed8">• tan(θ) = cot(α + β)</text>\n  <text x="220" y="186" font-size="11" fill="#1e3a8a">• tan(α) = 1/2, tan(β) = 1/2</text>\n  <text x="220" y="208" font-size="11" font-weight="bold" fill="#dc2626">• tan(θ) = 3 / 4</text>\n  <rect x="355" y="48" width="320" height="192" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Geometrik Çözüm Stratejisi (3 Adım)</text>\n  <text x="372" y="98" font-size="11" fill="#14532d"><tspan font-weight="bold">1. Adım:</tspan> İstenen açıyı (θ), dik üçgenlerin içindeki</text>\n  <text x="382" y="116" font-size="11" fill="#14532d">dar açıların (α ve β) toplamı veya farkı olarak yaz.</text>\n  <text x="372" y="142" font-size="11" fill="#14532d"><tspan font-weight="bold">2. Adım:</tspan> Dik üçgenlerden karşı/komşu oranlarıyla</text>\n  <text x="382" y="160" font-size="11" fill="#14532d">tan(α) ve tan(β) değerlerini rasyonel olarak bul.</text>\n  <text x="372" y="186" font-size="11" fill="#14532d"><tspan font-weight="bold">3. Adım:</tspan> tan(α ± β) formülünde yerine koy; eğer</text>\n  <text x="382" y="204" font-size="11" fill="#14532d">sin(θ) veya cos(θ) isteniyorsa dik üçgen çiz!</text>\n  <text x="515" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">İki iç açının toplamı komşu olmayan dış açıya eşittir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
